sp_widget.css:
:root{
  --navy:#0b2540;--teal:#0a7ea4;--teal-dark:#0c5f7c;
  --mint-1:#eafaf1;--mint-2:#dff3ea;--card-border:#e3e8ec;
  --text-dark:#16324a;--text-muted:#5b7085;--bg:#f5f7f9;
}
*{box-sizing:border-box;margin:0;padding:0;}
body{font-family:-apple-system,"Segoe UI",Helvetica,Arial,sans-serif;background:var(--bg);color:var(--text-dark);}
.topbar{background:var(--navy);color:#cfd8e3;font-size:12px;padding:6px 20px;display:flex;justify-content:space-between;align-items:center;}
.topbar .left{display:flex;gap:16px;align-items:center;}
.topbar .right{display:flex;gap:14px;align-items:center;opacity:.85;}
.header{background:#fff;padding:14px 32px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eceff2;}
.logo{font-size:19px;font-weight:700;color:var(--navy);letter-spacing:-0.3px;}
.logo span{color:var(--teal);}
.nav{display:flex;gap:28px;font-size:13px;color:var(--text-muted);}
.nav a{color:var(--text-muted);text-decoration:none;}
.nav a:hover{color:var(--teal-dark);}
.hero{background:linear-gradient(135deg,var(--mint-1) 0%,#d7ecdf 55%,var(--mint-2) 100%);padding:56px 20px 64px;text-align:center;}
.hero h1{font-size:34px;color:var(--navy);font-weight:700;margin-bottom:22px;}
.search{max-width:560px;margin:0 auto;position:relative;}
.search input{width:100%;padding:13px 46px 13px 18px;border:1px solid #d3dee2;border-radius:4px;font-size:14px;outline:none;background:#fff;}
.search button{position:absolute;right:6px;top:6px;bottom:6px;width:34px;background:var(--teal);border:none;border-radius:3px;color:#fff;cursor:pointer;}
.options{max-width:900px;margin:-30px auto 0;display:flex;justify-content:center;gap:64px;padding:0 20px 40px;flex-wrap:wrap;}
.option{text-align:center;max-width:220px;padding-top:36px;}
.option .icon{width:46px;height:46px;border-radius:50%;background:var(--teal);color:#fff;display:flex;align-items:center;justify-content:center;font-size:20px;margin:0 auto 12px;}
.option h3{font-size:14px;color:var(--navy);margin-bottom:6px;}
.option p{font-size:12px;color:var(--text-muted);line-height:1.4;}
.content{max-width:1100px;margin:0 auto;padding:0 24px 56px;display:grid;grid-template-columns:repeat(3,1fr);gap:20px;}
.card{background:#fff;border:1px solid var(--card-border);border-radius:6px;box-shadow:0 1px 3px rgba(20,40,60,0.05);padding:18px 20px;}
.card h4{font-size:13px;color:var(--navy);margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid #eef1f3;}
.card ul{list-style:none;}
.card li{font-size:12.5px;color:var(--teal-dark);padding:6px 0;border-bottom:1px dashed #f0f2f4;}
.card li:last-child{border-bottom:none;}
.status-banner{background:var(--mint-1);border-left:3px solid #4ca87a;padding:10px 12px;font-size:12px;color:#2f5c44;border-radius:3px;margin-bottom:10px;}
.stars{color:#e4a300;font-size:12px;}
@media(max-width:720px){.content{grid-template-columns:1fr;}.options{gap:28px;}.hero h1{font-size:26px;}}

sp_widget.script:
(function() {
    data.requests = [];
    var gr = new GlideRecord('x_2238299_itasse_0_asset_request');
    gr.addQuery('u_requester', gs.getUserID());
    gr.orderByDesc('sys_created_on');
    gr.query();
    while (gr.next()) {
        data.requests.push({
            item: gr.u_requested_item.toString(),
            priority: gr.u_priority.getDisplayValue(),
            approval: gr.u_approval_status.getDisplayValue(),
            state: gr.u_state.getDisplayValue()
        });
    }
})();
